        "maximum": 365,
        "description": "Number of days between booking date and pickup date"
      },
      "transmission_type": {
        "type": "string",
        "enum": ["automatic", "manual"]
      },
      "pickup_location_type": {
        "type": "string",
        "enum": ["airport", "downtown", "rail_station", "neighborhood"]
      },
      "payment_timing": {
        "type": "string",
        "enum": ["prepaid", "pay_at_counter", "mixed"]
      },
      "has_unlimited_mileage": { "type": "boolean" },
      "includes_collision_coverage": { "type": "boolean" },
      "includes_child_seat": { "type": "boolean" },
      "free_cancellation": { "type": "boolean" }
    },
    "required": [
      "rental_company",
      "vehicle_class",
      "daily_rate_usd",
      "rental_days",
      "pickup_offset_days",
      "transmission_type",
      "pickup_location_type",
      "payment_timing",
